import * as T from './vendor/three.module.js';
import {flightWorld} from './game/flight.js';
import {CampNetwork,sectorPoint,homeReady,jumpTo,HOME_RADIUS,DOCK_RADIUS,HOME_Y} from './camp-rules.js';
export const SLOT_COLORS=[0x9de9e0,0xd29bea,0xf1b082,0xa6c97c,0x83b6ed,0xe78d9b,0xdbd48a,0xa9a3e9];
// Authored ground and fixed private departure docks. Empty castle plots never
