  mesh(new T.CylinderGeometry(9,2,20,8),mats.soil,d.x,HOME_Y-12,d.z);
  mesh(new T.BoxGeometry(2,2,2),mats.stone,d.x+Math.cos(i*Math.PI/4+Math.PI/2)*5,HOME_Y+1,d.z+Math.sin(i*Math.PI/4+Math.PI/2)*5,true);
  const flag=mesh(new T.BoxGeometry(2.2,2,.15),color,d.x,HOME_Y+7,d.z+6);mesh(new T.CylinderGeometry(.18,.18,7,6),mats.bark,d.x,HOME_Y+3.5,d.z+6);flag.userData.slot=i;
